ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET
  display_name = EXCLUDED.display_name,
  xp = EXCLUDED.xp,
  onboarded = true,
  intro_completed = true,
  active_dragon_id = EXCLUDED.active_dragon_id,
  dragon_progress = EXCLUDED.dragon_progress;

